/**
 * SortableJS - Minimal Drag & Drop Implementation for EZGalaxy
 */
(function(global) {
    'use strict';

    class Sortable {
        constructor(el, options = {}) {
            this.el = el;
            this.options = {
                group: null,
                sort: true,
                disabled: false,
                animation: 150,
                handle: null,
                filter: null,
                draggable: '>*',
                ghostClass: 'sortable-ghost',
                chosenClass: 'sortable-chosen',
                dragClass: 'sortable-drag',
                dataIdAttr: 'data-id',
                onStart: null,
                onEnd: null,
                onAdd: null,
                onUpdate: null,
                onSort: null,
                onRemove: null,
                onFilter: null,
                onMove: null,
                onClone: null,
                onChange: null,
                ...options
            };

            this.dragEl = null;
            this.ghostEl = null;
            this.cloneEl = null;
            this.nextEl = null;
            this.oldIndex = null;
            this.newIndex = null;

            this._initEvents();
        }

        _initEvents() {
            this.el.addEventListener('mousedown', this._onMouseDown.bind(this));
            this.el.addEventListener('touchstart', this._onTouchStart.bind(this), { passive: false });
        }

        _getItems() {
            const selector = this.options.draggable;
            if (selector === '>*') {
                return Array.from(this.el.children);
            }
            return Array.from(this.el.querySelectorAll(selector));
        }

        _onMouseDown(e) {
            if (this.options.disabled) return;
            
            const target = e.target;
            const items = this._getItems();
            
            // Find the draggable element
            let dragEl = null;
            for (const item of items) {
                if (item.contains(target)) {
                    // Check handle
                    if (this.options.handle) {
                        if (!target.closest(this.options.handle)) continue;
                    }
                    dragEl = item;
                    break;
                }
            }

            if (!dragEl) return;

            // Check filter
            if (this.options.filter && target.matches(this.options.filter)) {
                this._dispatch('filter', { item: target });
                return;
            }

            e.preventDefault();
            this._startDrag(dragEl, e.clientX, e.clientY);

            document.addEventListener('mousemove', this._onMouseMove.bind(this));
            document.addEventListener('mouseup', this._onMouseUp.bind(this));
        }

        _onTouchStart(e) {
            if (this.options.disabled) return;
            if (e.touches.length !== 1) return;

            const touch = e.touches[0];
            const target = touch.target;
            const items = this._getItems();

            let dragEl = null;
            for (const item of items) {
                if (item.contains(target)) {
                    if (this.options.handle && !target.closest(this.options.handle)) continue;
                    dragEl = item;
                    break;
                }
            }

            if (!dragEl) return;

            e.preventDefault();
            this._startDrag(dragEl, touch.clientX, touch.clientY);

            document.addEventListener('touchmove', this._onTouchMove.bind(this), { passive: false });
            document.addEventListener('touchend', this._onTouchEnd.bind(this));
        }

        _startDrag(el, x, y) {
            this.dragEl = el;
            this.nextEl = el.nextSibling;
            this.oldIndex = this._getItems().indexOf(el);
            this.startX = x;
            this.startY = y;
            this.offsetX = x - el.getBoundingClientRect().left;
            this.offsetY = y - el.getBoundingClientRect().top;

            // Add classes
            el.classList.add(this.options.chosenClass);

            // Create ghost
            this.ghostEl = el.cloneNode(true);
            this.ghostEl.classList.add(this.options.ghostClass);
            this.ghostEl.style.position = 'fixed';
            this.ghostEl.style.zIndex = '10000';
            this.ghostEl.style.pointerEvents = 'none';
            this.ghostEl.style.opacity = '0.8';
            this.ghostEl.style.transform = 'scale(1.02)';
            this.ghostEl.style.left = `${x - this.offsetX}px`;
            this.ghostEl.style.top = `${y - this.offsetY}px`;
            this.ghostEl.style.width = `${el.offsetWidth}px`;
            document.body.appendChild(this.ghostEl);

            // Hide original
            el.style.opacity = '0.4';

            this._dispatch('start', {
                item: el,
                oldIndex: this.oldIndex
            });
        }

        _onMouseMove(e) {
            this._onDrag(e.clientX, e.clientY);
        }

        _onTouchMove(e) {
            e.preventDefault();
            const touch = e.touches[0];
            this._onDrag(touch.clientX, touch.clientY);
        }

        _onDrag(x, y) {
            if (!this.dragEl) return;

            // Move ghost
            this.ghostEl.style.left = `${x - this.offsetX}px`;
            this.ghostEl.style.top = `${y - this.offsetY}px`;

            // Find element under cursor
            this.ghostEl.style.display = 'none';
            const elemBelow = document.elementFromPoint(x, y);
            this.ghostEl.style.display = '';

            if (!elemBelow) return;

            // Find sortable container and item
            const items = this._getItems();
            let targetEl = null;

            for (const item of items) {
                if (item !== this.dragEl && item.contains(elemBelow)) {
                    targetEl = item;
                    break;
                }
            }

            if (targetEl && this.options.sort) {
                const rect = targetEl.getBoundingClientRect();
                const midY = rect.top + rect.height / 2;

                if (y < midY) {
                    this.el.insertBefore(this.dragEl, targetEl);
                } else {
                    this.el.insertBefore(this.dragEl, targetEl.nextSibling);
                }

                this._dispatch('change', { item: this.dragEl });
            }
        }

        _onMouseUp(e) {
            this._endDrag();
            document.removeEventListener('mousemove', this._onMouseMove.bind(this));
            document.removeEventListener('mouseup', this._onMouseUp.bind(this));
        }

        _onTouchEnd(e) {
            this._endDrag();
            document.removeEventListener('touchmove', this._onTouchMove.bind(this));
            document.removeEventListener('touchend', this._onTouchEnd.bind(this));
        }

        _endDrag() {
            if (!this.dragEl) return;

            // Remove ghost
            if (this.ghostEl && this.ghostEl.parentNode) {
                this.ghostEl.parentNode.removeChild(this.ghostEl);
            }

            // Restore original
            this.dragEl.style.opacity = '';
            this.dragEl.classList.remove(this.options.chosenClass);

            // Calculate new index
            this.newIndex = this._getItems().indexOf(this.dragEl);

            // Dispatch end event
            this._dispatch('end', {
                item: this.dragEl,
                oldIndex: this.oldIndex,
                newIndex: this.newIndex,
                from: this.el,
                to: this.el
            });

            if (this.oldIndex !== this.newIndex) {
                this._dispatch('update', {
                    item: this.dragEl,
                    oldIndex: this.oldIndex,
                    newIndex: this.newIndex
                });
                this._dispatch('sort', {
                    item: this.dragEl,
                    oldIndex: this.oldIndex,
                    newIndex: this.newIndex
                });
            }

            this.dragEl = null;
            this.ghostEl = null;
            this.oldIndex = null;
            this.newIndex = null;
        }

        _dispatch(name, detail) {
            const callback = this.options[`on${name.charAt(0).toUpperCase() + name.slice(1)}`];
            if (typeof callback === 'function') {
                callback(detail);
            }

            this.el.dispatchEvent(new CustomEvent(`sortable:${name}`, { detail }));
        }

        toArray() {
            const attr = this.options.dataIdAttr;
            return this._getItems().map(el => el.getAttribute(attr) || '');
        }

        sort(order) {
            const items = this._getItems();
            const itemMap = new Map();
            items.forEach(item => {
                const id = item.getAttribute(this.options.dataIdAttr);
                if (id) itemMap.set(id, item);
            });

            order.forEach(id => {
                const item = itemMap.get(id);
                if (item) this.el.appendChild(item);
            });
        }

        option(name, value) {
            if (value === undefined) {
                return this.options[name];
            }
            this.options[name] = value;
        }

        destroy() {
            this.el.removeEventListener('mousedown', this._onMouseDown.bind(this));
            this.el.removeEventListener('touchstart', this._onTouchStart.bind(this));
        }

        static create(el, options) {
            return new Sortable(el, options);
        }
    }

    // Expose globally
    global.Sortable = Sortable;

})(typeof window !== 'undefined' ? window : this);
